<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Plot Purchase {{ $purchase->purchase_number }}</title>
<style>*{box-sizing:border-box}body{margin:0;padding:26px;background:#eef2f7;color:#182433;font:13px Arial,sans-serif}.sheet{max-width:980px;margin:auto;padding:30px;background:#fff;border:1px solid #dbe3ed;border-radius:10px}h1,h2{text-align:center;margin:0}h1{font-size:23px}h2{font-size:16px;font-weight:500;color:#526174;margin:5px 0 22px}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:18px}.meta div{border:1px solid #dfe6ee;padding:10px;border-radius:6px}.label{display:block;color:#68778a;font-size:10px;text-transform:uppercase;margin-bottom:4px}.table{width:100%;border-collapse:collapse}.table th,.table td{border:1px solid #cfd8e3;padding:8px;text-align:left}.table th{background:#26343b;color:#fff}.num{text-align:right!important;white-space:nowrap}.total{font-weight:700;background:#eef3f7}.narration{margin-top:15px;padding:10px;border:1px solid #dfe6ee}.actions{max-width:980px;margin:12px auto;text-align:right}.actions button{padding:9px 18px;border:0;border-radius:5px;background:#1677ff;color:#fff;cursor:pointer}@media print{body{padding:0;background:#fff}.sheet{border:0;border-radius:0}.actions{display:none}}</style></head>
<body><main class="sheet"><h1>{{ Setting::getValue('app_name') }}</h1><h2>Plot Purchase Voucher</h2>
<section class="meta"><div><span class="label">Voucher number</span><strong>{{ $purchase->purchase_number }}</strong></div><div><span class="label">Date</span><strong>{{ $purchase->purchase_date }}</strong></div><div><span class="label">Seller account</span><strong>{{ $purchase->seller ?: 'Seller account' }}</strong></div></section>
<table class="table"><thead><tr><th>#</th><th>Plot code</th><th>Description</th><th class="num">Area</th><th>Unit</th><th class="num">Rate</th><th class="num">Amount</th></tr></thead><tbody>@foreach($items as $i => $item)<tr><td>{{ $i + 1 }}</td><td>{{ $item->plot_code }}</td><td>{{ $item->description }}</td><td class="num">{{ number_format((float)$item->area, 4) }}</td><td>{{ $item->unit }}</td><td class="num">{{ number_format((float)$item->unit_rate, 2) }}</td><td class="num">{{ number_format((float)$item->amount, 2) }}</td></tr>@endforeach</tbody><tfoot><tr class="total"><td colspan="6" class="num">Purchase total</td><td class="num">{{ number_format((float)$purchase->amount, 2) }}</td></tr></tfoot></table>
<div class="narration"><span class="label">Narration</span>{{ $purchase->narration }}</div></main><div class="actions"><button type="button" onclick="window.print()">Print voucher</button></div></body></html>
